I'll look at the core named entities and their rating actions first.

```sql
SELECT * FROM entities WHERE entity_id NOT SIMILAR TO 'E1[0-9]{3}' AND entity_id NOT SIMILAR TO 'E50[0-9]{2}' AND entity_id NOT SIMILAR TO 'E51[0-9]{2}' ORDER BY entity_id;
```

```sql
SELECT * FROM rating_actions WHERE rated_id IN ('E01','E02','E03','E04','E05','E06','E07','E08','E09','E10','E11','E12','E13','E14','E15','E16','E17','E18','E19','E20','I01','I02','I03','I04','I05','I07') ORDER BY rated_id, rating_type, ccy_basis, date;
```

```sql
SELECT * FROM instruments WHERE instrument_id NOT SIMILAR TO 'I1[0-9]{3}' ORDER BY instrument_id;
```

```sql
SELECT lei, string_agg(entity_id||'|'||name||'|'||country||'|'||coalesce(parent_id,'')||'|'||source_system, ' ;; ') AS recs FROM entities WHERE lei<>'' GROUP BY lei HAVING count(*)>1 ORDER BY lei;
```

```sql
SELECT rating_type, ccy_basis, action, count(*) FROM rating_actions GROUP BY ALL ORDER BY ALL;
```

```sql
SELECT * FROM rating_actions WHERE rated_id IN ('CV','VD') OR rating_type='CC' ORDER BY rated_id, date;
```

```sql
SELECT * FROM rating_actions WHERE rated_id LIKE 'E5%' OR rated_id LIKE 'I5%' ORDER BY rated_id, rating_type, ccy_basis, date;
```
